		~HueSyncConfig()
		{
			_saveSem.Dispose();
		}

		public static async Task Init()
		{
			Instance = await _configDataStore.Load<HueSyncConfig>();
		}

		private void SetIntensity(HueSyncType.VideoMode mode, HueSyncType.Intensity intensity)
		{
			if (intensity > HueSyncType.Intensity.None && intensity <= HueSyncType.Intensity.Max && VideoModes[(int)mode].Preset != intensity)
			{
				VideoModes[(int)mode].Preset = intensity;
				Save();
			}
		}

		public static async Task Delete()
		{
			_configDataStore.Delete();
			Instance = await _configDataStore.Load<HueSyncConfig>();
		}

		private static void Save()
		{
			if (Instance != null)
			{
				Task.Run(async delegate
				{
					_saveSem.Wait();
					Task<bool> task = _configDataStore.Save(Instance);
					await task;
					_saveSem.Release();
				});
			}
		}
	}
